<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, ScanSearch, Wrench, Download, Check, Box, RotateCcw } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import ThreePreview, {type DisplayMode} from '../components/ThreePreview.vue'
import AssetPreview from '../components/AssetPreview.vue'
import { useAssets, metric } from '../services/studio'
import { formatApiDate } from '../utils/date'
import api from '../services/api'
const route=useRoute(),router=useRouter(),{assets,load}=useAssets(),taskId=computed(()=>Number(route.params.taskId)||0)
const asset=computed(()=>assets.value.find(item=>item.id===taskId.value)),report=ref<any>(null), revisions=ref<any[]>([]),selected=ref(0),url=ref(''),mode=ref<DisplayMode>('material')
const loading=ref(false),busy=ref(''),error=ref(''),fileError=ref(''), options=reactive({name:'结构清理版本',clean_faces:true,fix_winding:true,fill_holes:false})
const review=reactive({face:false,back:false,texture:false,silhouette:false,note:''}),saving=ref(false)
const revision=computed(()=>revisions.value.find(item=>item.id===selected.value)),issues=computed(()=>report.value?.meshes?.filter((m:any)=>m.degenerate_faces||m.duplicate_faces||m.nonmanifold_edges||m.boundary_edges||!m.winding_consistent)||[])
let requestVersion=0
async function refresh() { if(!taskId.value)return; loading.value=true;error.value='';try { const {data}=await api.get(`/studio/assets/${taskId.value}/inspection`);report.value=data.report;revisions.value=data.revisions;Object.assign(review,{face:false,back:false,texture:false,silhouette:false,note:''},data.review);if(!selected.value)selected.value=data.revisions[0]?.id||0 }catch(e:any){error.value=e.message}finally{loading.value=false} }
async function inspect() { if(busy.value)return;busy.value='inspect';error.value='';try{report.value=(await api.post(`/studio/assets/${taskId.value}/inspect`,{}, {timeout:120000})).data;ElMessage.success('结构检查已完成并保存')}catch(e:any){error.value=e.message}finally{busy.value=''} }
async function repair() { if(busy.value)return;busy.value='repair';error.value='';try{const{data}=await api.post(`/studio/assets/${taskId.value}/repair`,options,{timeout:180000});selected.value=data.id;await refresh();ElMessage.success('修复版本已保存，可以对照查看或下载')}catch(e:any){error.value=e.message}finally{busy.value=''} }
async function loadRevision() { const version=++requestVersion;const id=selected.value;if(url.value)URL.revokeObjectURL(url.value);url.value='';fileError.value='';if(!id)return;try{const{data}=await api.get(`/studio/assets/${taskId.value}/revisions/${id}/file`,{responseType:'blob',timeout:60000});if(version===requestVersion)url.value=URL.createObjectURL(data)}catch(e:any){if(version===requestVersion)fileError.value=e.message} }
async function saveReview() {saving.value=true;error.value='';try{await api.put(`/studio/assets/${taskId.value}/review`,review);ElMessage.success('原模型外观复核记录已保存')}catch(e:any){error.value=e.message}finally{saving.value=false} }
function download(){if(!url.value||!revision.value)return;const a=document.createElement('a');a.href=url.value;a.download=`lingjing-${taskId.value}-repair-${selected.value}.glb`;a.click()}
onMounted(async()=>{await load();await refresh()});watch(selected,loadRevision)
onUnmounted(()=>{requestVersion++;if(url.value)URL.revokeObjectURL(url.value)})
</script>
<template><main class="page tool-page repair-page"><header class="library-heading"><div><p class="eyebrow">检查 · 修整 · 留存</p><h1>模型检查与修复</h1><p>从结构问题开始修整，原模型与修复版本可以随时对照。</p></div><RouterLink class="library-button quiet" to="/library"><ArrowLeft :size="15" />模型资产</RouterLink></header><div class="library-toolbar"><select class="library-select repair-select" aria-label="选择需要检查的模型" :value="taskId" :disabled="!!busy" @change="router.push(`/repair/${($event.target as HTMLSelectElement).value}`)"><option :value="0" disabled>选择已完成的 GLB 模型</option><option v-for="item in assets.filter(a=>a.format==='glb' && a.preview_available)" :key="item.id" :value="item.id">{{item.name}} · #{{item.id}}</option></select><RouterLink class="text-link" to="/guide#inspection">了解检查范围 →</RouterLink></div><p v-if="error" class="library-error" role="alert">{{error}}</p><div v-if="!taskId" class="tool-card prepare-empty"><Box :size="36" /><h2>选择一个模型开始检查</h2><p>检查读取已保存的文件，不需要重新生成。</p></div><template v-else><div class="repair-comparison"><section class="tool-card repair-slot"><div class="tool-section-head"><h2>原始模型 <small>#{{taskId}}</small></h2><span class="tool-badge">原文件</span></div><div class="repair-canvas"><AssetPreview v-if="asset" :task-id="taskId" format="glb" :available="asset.preview_available" :display-mode="mode" /><span v-else class="tool-hint">{{loading?'正在读取模型…':'此模型不可用，请从资产列表重新选择'}}</span></div><p class="tool-hint">{{asset?.name || '原模型'}} · 原始生成文件保持保留。</p></section><section class="tool-card repair-slot"><div class="tool-section-head"><h2>修复版本</h2><select v-model="selected" class="library-select" aria-label="选择修复版本"><option :value="0">选择修复版本</option><option v-for="item in revisions" :key="item.id" :value="item.id">{{item.name}} · #{{item.id}}</option></select></div><div class="repair-canvas"><ThreePreview v-if="url" :model-url="url" model-format="glb" :display-mode="mode" @error="fileError=$event" /><div v-else class="prepare-empty"><Wrench :size="30" /><p>{{selected?'正在加载修复模型…':'完成下方修复后，在这里查看结果。'}}</p></div></div><p v-if="fileError" class="library-error" role="alert">{{fileError}} <button class="text-link" @click="loadRevision">重新加载</button></p><div class="library-actions"><button class="library-button quiet" :disabled="!url" @click="download"><Download :size="14" />下载修复 GLB</button><span v-if="revision" class="tool-hint">{{formatApiDate(revision.created_at)}}</span></div></section></div><div class="library-toolbar"><div class="library-actions"><button v-for="item in [{id:'material',label:'材质'},{id:'solid',label:'轮廓'},{id:'wireframe',label:'线框'}]" :key="item.id" class="library-button quiet" :aria-pressed="mode===item.id" @click="mode=item.id as DisplayMode">{{item.label}}</button></div><p class="tool-hint">两侧可分别旋转查看；按模型名称定位下方问题。</p></div><div class="repair-workbench"><section class="tool-card"><div class="tool-section-head"><div><p class="eyebrow">几何与贴图坐标</p><h2>结构检查</h2></div><button class="library-button" :disabled="!!busy || !asset" @click="inspect"><ScanSearch :size="15" />{{busy==='inspect'?'检查中…':report?'重新检查':'开始检查'}}</button></div><div v-if="report"><dl class="tool-metrics"><div><dt>实际面数</dt><dd>{{metric(report.faces)}}</dd></div><div><dt>网格数量</dt><dd>{{report.meshes.length}}</dd></div><div><dt>文件大小</dt><dd>{{report.size_mb}} MB</dd></div></dl><div class="repair-mesh-list"><article v-for="mesh in report.meshes" :key="mesh.name"><h3>{{mesh.name}}</h3><div class="repair-findings"><span :class="{'is-issue':mesh.degenerate_faces>0}">退化面 {{mesh.degenerate_faces}}</span><span :class="{'is-issue':mesh.duplicate_faces>0}">重复面 {{mesh.duplicate_faces}}</span><span :class="{'is-issue':mesh.boundary_edges>0}">边界边 {{mesh.boundary_edges}}</span><span :class="{'is-issue':mesh.nonmanifold_edges>0}">非流形边 {{mesh.nonmanifold_edges}}</span><span>{{mesh.winding_consistent?'绕序一致':'绕序需检查'}}</span><span>{{mesh.has_uv?(mesh.uv_valid?'UV 坐标有效':'UV 需检查'):'无 UV 坐标'}}</span></div></article></div><p class="tool-hint">{{report.note}}</p></div><p v-else class="tool-hint">检查会读取真实网格，列出每个网格的退化面、重复面、边界边、非流形边和 UV 状态。支持 80MB / 200 万面以内的 GLB。</p></section><section class="tool-card"><div class="tool-section-head"><div><p class="eyebrow">保存为独立版本</p><h2>选择修复操作</h2></div><Wrench :size="21" /></div><form class="tool-form" @submit.prevent="repair"><label>版本名称<input v-model="options.name" class="library-input" required maxlength="100" :disabled="!!busy" /></label><label class="tool-check"><input v-model="options.clean_faces" type="checkbox" :disabled="!!busy" />清理退化面、重复面与未引用顶点</label><label class="tool-check"><input v-model="options.fix_winding" type="checkbox" :disabled="!!busy" />修正相邻三角面的绕序</label><label class="tool-check"><input v-model="options.fill_holes" type="checkbox" :disabled="!!busy" />填补三角或四边小孔（仅无 UV 网格）</label><p class="tool-hint">保留 UV 接缝与网格部件。带骨骼、动画或形态键的模型不执行自动修复；头发缺失、脸部相似度和纹理错位需要另行修整。</p><button class="library-button primary-action" :disabled="!!busy || !asset || !options.name.trim() || !(options.clean_faces||options.fix_winding||options.fill_holes)">{{busy==='repair'?'正在处理并保存…':'修复并保存新版本'}}</button></form></section></div><section v-if="revision" class="tool-card repair-result"><div class="tool-section-head"><h2>{{revision.name}} · 修复结果</h2><span class="tool-badge"><Check :size="13" />已保存</span></div><div class="comparison-table-wrap"><table class="comparison-table"><thead><tr><th>对比项</th><th>原模型</th><th>修复版本</th></tr></thead><tbody><tr v-for="item in [{key:'faces',label:'面数'},{key:'vertices',label:'顶点数'},{key:'size_mb',label:'文件大小 / MB'}]" :key="item.key"><th>{{item.label}}</th><td>{{metric(revision.report.before[item.key])}}</td><td>{{metric(revision.report.after[item.key])}}</td></tr><tr><th>退化面</th><td>{{revision.report.before.meshes.reduce((s:number,m:any)=>s+m.degenerate_faces,0)}}</td><td>{{revision.report.after.meshes.reduce((s:number,m:any)=>s+m.degenerate_faces,0)}}</td></tr><tr><th>重复面</th><td>{{revision.report.before.meshes.reduce((s:number,m:any)=>s+m.duplicate_faces,0)}}</td><td>{{revision.report.after.meshes.reduce((s:number,m:any)=>s+m.duplicate_faces,0)}}</td></tr></tbody></table></div><p v-for="warning in revision.report.warnings" :key="warning" class="tool-hint">{{warning}}</p><p class="tool-hint">数值变化用于核对操作结果；请旋转模型确认外观。若原模型没有这些结构问题，修复前后可能相同。</p></section><section class="tool-card repair-review"><div class="tool-section-head"><div><p class="eyebrow">人的判断同样重要</p><h2>原模型外观复核</h2></div><span class="tool-badge">人工记录</span></div><form class="tool-form" @submit.prevent="saveReview"><div class="review-checks"><label v-for="item in [{key:'face',label:'脸部位置与五官已检查'},{key:'back',label:'背面与侧面已检查'},{key:'texture',label:'纹理方向与接缝已检查'},{key:'silhouette',label:'主体轮廓与配饰已检查'}]" :key="item.key" class="tool-check"><input v-model="(review as any)[item.key]" type="checkbox" :disabled="saving" />{{item.label}}</label></div><label>复核备注<textarea v-model="review.note" class="library-input" rows="3" maxlength="1000" placeholder="例如：正脸位置正确，背部头发仍有缺失，需要继续修整。" :disabled="saving"></textarea></label><p class="tool-hint">勾选表示已人工查看，不代表自动判定通过。记录针对原模型；修复版本请在备注中注明版本编号。</p><button class="library-button" :disabled="saving || !report">{{saving?'保存中…':'保存复核记录'}}</button></form></section></template></main></template>
